const { test } = require('node:test');
const assert = require('node:assert/strict');

// Required inside each test so every case reports its own failure.
const load = () => require('./add.js').add;

test('add returns the sum of two positive integers', () => {
  const add = load();
  assert.equal(add(2, 3), 5);
});

test('add returns zero when both operands are zero', () => {
  const add = load();
  assert.equal(add(0, 0), 0);
});

test('add handles negative operands', () => {
  const add = load();
  assert.equal(add(-4, 1), -3);
  assert.equal(add(-4, -6), -10);
});

test('add handles non-integer operands', () => {
  const add = load();
  assert.equal(add(0.5, 0.25), 0.75);
});

